          "foodContext": "霍克斯莫尔以牛排和海鲜为主，其官方菜单也体现了这两类菜品。餐厅称，七面钟店的厨师最初用优质牛肉边角料制作肉酱，作为员工餐并搭配剩余的约克郡布丁；后来加入培根，这道菜才进入菜单。这是餐厅对自家菜品由来的描述，并非对肉酱或约克郡布丁整体起源的说明。",
