          "history": "据《France Today》报道，贝特朗·奥博诺和格温艾尔·卡多雷于1997年开设了Bistrot Paul Bert。奥博诺曾从事金融工作，后来希望在自己的故乡巴黎开一家热情待客的餐馆。巴黎餐饮界兴起“bistronomie”（小酒馆与精致料理融合）之际，这家店选择坚持传统法式小酒馆菜式。"
