          "history": "Paris by Mouth는 L’As du Fallafel이 1979년부터 rue des Rosiers에서 손님을 맞아 왔다고 소개합니다. The Forward가 인용한 식당 메뉴의 설명에 따르면, 이 모험은 1970년대 후반 이스라엘을 떠나 중동의 맛을 프랑스로 가져온 프랑스·이스라엘 출신 부부 Isaac과 Daisy와 함께 시작됐습니다. 이 가족 이야기는 식당 메뉴에 실린 설명으로 전해진 내용입니다."
