          "history": "Carette의 공식 연혁에 따르면 장 카레트는 1927년 트로카데로 광장에 찻집을 열었습니다. 이곳은 곧 세련된 파리 시민들이 모이는 장소가 되었고, 초창기부터 하우스 마카롱을 선보였습니다."
