          "history": "カフェ・ド・フロールの公式沿革によると、店は第三共和政初期、1887年ごろにサン＝ジェルマン＝デ＝プレに現れたとされています（年は「おそらく」と記載）。パリの観光案内は、ギヨーム・アポリネールをはじめ、20世紀の文学・芸術界の人々が集う場所だったと紹介しています。1940年代にはジャン＝ポール・サルトルとシモーヌ・ド・ボーヴォワールがここで執筆し、友人たちと交流し、戦後の知的文化を象徴するカフェとなりました。"
