          "history": "Café de Flore 的官方沿革称，这家咖啡馆在第三共和国初期、约 1887 年出现在圣日耳曼德佩（原文对年份注明“可能”）。巴黎旅游资料将它描述为 20 世纪文学与艺术界人士的聚会场所，其中包括纪尧姆·阿波利奈尔。20 世纪 40 年代，萨特和西蒙娜·德·波伏娃曾在此工作、会友，使咖啡馆成为战后知识界生活的象征之一。"
