        "ja": {
          "foodContext": "ブイヤベースはマルセイユを代表する魚料理で、売り物にならない漁獲物を漁師が使った料理に由来するという説明が広く受け入れられています。マルセイユ観光局によると、1980年に一部の飲食店が基本の食材と提供方法を定める憲章を作りました。料理名の語源には異説があるため、ひとつの説を確定事項として扱いません。",
          "history": "ル・ミラマールの公式紹介によると、店は1965年にミンゲリャ兄弟が買収し、その後まもなく、魚介料理とブイヤベースで知られるレストランになりました。2003年にはブッファ家が引き継ぎ、クリスチャン・ブッファが店のブイヤベースの伝統を継承しています。店の説明では、彼は2008年からブイヤベース憲章の副会長を務めています。"
        },
        "ko": {
          "foodContext": "부야베스는 마르세유의 대표적인 생선 요리로, 남은 어획물을 활용한 어민 음식에서 비롯되었다는 설명이 널리 받아들여집니다. 마르세유 관광청에 따르면 1980년 일부 식당이 재료와 차림의 기본 기준을 제시하는 헌장을 만들었습니다. 요리 이름의 어원은 논쟁 중이므로 확정된 사실처럼 다루지 않습니다.",
          "history": "르 미라마르의 자체 역사 소개에 따르면, 이 식당은 1965년 망구엘라 형제에게 인수된 뒤 곧 해산물과 부야베스로 알려진 미식 레스토랑이 되었습니다. 부파 가족은 2003년 식당을 인수했으며, 크리스티앙 부파는 기존의 부야베스 전통을 이어 왔습니다. 식당 측은 그가 2008년부터 부야베스 헌장 부회장을 맡고 있다고 밝힙니다."
        },
        "zh": {
          "foodContext": "马赛鱼汤是马赛具有代表性的鱼料理，普遍认为它源自渔民利用未挑选出售的渔获烹制的家常食物。马赛旅游局介绍，部分餐厅于1980年制定宪章，说明这道菜的基本食材与上桌方式。菜名词源仍有争议，因此不把任何单一说法当作定论。",
          "history": "Le Miramar 自身的历史介绍称，餐厅于1965年由 Minguella 兄弟收购，此后不久便成为以海鲜和马赛鱼汤闻名的餐饮场所。Buffa 家族于2003年接手，Christian Buffa 延续了餐厅的马赛鱼汤传统。餐厅称他自2008年起担任《马赛鱼汤宪章》副主席。"
        }
