          "history": "据店家自己的历史介绍，葡萄牙修道院于1834年关闭后，Pastéis de Belém于1837年开始在附近制糖厂附属建筑内烘制，所用配方据称源自热罗尼莫斯修道院。修道院相关人士为谋生而开始售卖糕点的说法属于店家的叙述，本文查阅的资料并未以一手史料独立证实这一细节。"
