          "foodContext": "Its food context is Portuguese petiscos—small tavern dishes to share—and familiar Portuguese flavors. The menu has been described as changing, sometimes pairing traditional flavors with influences from elsewhere. Reliable sources do not establish a particular signature dish's origin here, so no individual dish origin is claimed.",
          "history": "Chef André Magalhães opened Taberna da Rua das Flores in central Lisbon in 2012. Bloomberg places the small restaurant within the “movimento taberneiro,” a wave of chefs seeking to safeguard classic Portuguese tavern culture. A travel guide describes its aim as reviving the atmosphere and cooking of the simple taverns once common in working-class districts."
