          "history": "シェフのアンドレ・マガリャンイスは、2012年にリスボン中心部でタベルナ・ダ・ルア・ダス・フローレスを開きました。Bloombergは、小さなこの店を、伝統的なポルトガルのタベルナ文化を守ろうとする料理人たちの「モヴィメント・タベルネイロ」の一環として紹介しています。旅行ガイドによれば、かつて労働者地区に広くあった素朴なタベルナの雰囲気と料理を再現することを目指しました。"
