          "history": "셰프 앙드레 마갈량이스는 2012년 리스본 중심부에 타베르나 다 루아 다스 플로레스(Taberna da Rua das Flores)를 열었습니다. 블룸버그는 이 작은 식당을 전통 포르투갈 요리를 다시 조명하고 리스본의 오래된 타베르나 문화를 지키려는 ‘모비멘투 타베르네이루’ 흐름의 일부로 소개합니다. 이곳은 옛 동네 타베르나의 분위기와 요리를 현대적으로 되살리려는 취지로 설명되어 왔습니다."
