          "history": "2014年の同時期の報道によると、カンティーニョ・ド・アヴィレーズはジョゼ・アヴィレーズがポルトに開いた最初の店でした。同記事は、ポルトガル料理を現代的に解釈した店として紹介しています。公式紹介では、ルア・ムジーニョ・ダ・シルヴェイラに位置し、シェフの海外での食体験に影響を受けたポルトガル風の料理を掲げています。"
