          "history": "一篇2014年的同期报道说，Cantinho do Avillez 是主厨 José Avillez 在波尔图开设的首家餐厅。报道将其描述为对葡萄牙料理的现代诠释。餐厅官方介绍称，店址位于 Rua Mouzinho da Silveira，菜式以葡萄牙风味为基础，并受到 Avillez 海外美食经历的影响。"
