          "foodContext": "Gazela is best known for the Porto-style cachorrinho, a small pressed, grilled roll with sausage, cheese and spicy piri-piri sauce.[3][4] Taste Porto places its emergence in the early 1960s and says Gazela is often credited as its birthplace, but the sources reviewed do not establish a definitive inventor or origin.[1][3]",
