          "history": "포르투갈 정부의 「Comércio com História」 자료는 Cervejaria Gazela가 1962년에 문을 열었다고 기록합니다.[1] 현 소유주는 1970년부터 이곳에서 일했으며, 상 조앙 극장 근처의 작은 식당은 공연예술인들이 즐겨 찾는 곳이 되었다고 합니다.[1] Anthony Bourdain이 2017년 포르투갈 편을 이곳에서 촬영한 뒤 더 널리 알려졌다고도 전합니다.[1]"
