          "foodContext": "A travesseiro is a pillow-shaped pastry with an egg-cream filling and an almond note. Casa Piriquita and Sintra’s regional tourism source place its introduction here in the 1940s, though accounts differ about the creator’s exact relationship to the founders.",
          "history": "Casa Piriquita began as a bakery founded in 1862 by baker Amaro dos Santos and his wife, Constância Gomes. It first made Sintra’s queijadas, and the bakery later became a pastry shop. In the 1940s, travesseiros were introduced here and became one of Sintra’s best-known sweets."
