          "history": "Casa Piriquitaは、パン職人Amaro dos Santosと妻Constância Gomesが1862年に始めたパン屋に由来します。当初はシントラ名物のケイジャーダを作り、その後、菓子店へと発展しました。1940年代にはこの店でトラヴェセイロが登場し、シントラを代表する菓子の一つになりました。"
