          "history": "Casa Piriquita는 1862년 제빵사 Amaro dos Santos와 그의 아내 Constância Gomes가 시작한 빵집에서 출발했습니다. 처음에는 신트라의 치즈 타르트인 케이자다를 만들었고, 빵집은 뒤이어 제과점으로 발전했습니다. 1940년대에는 이곳에서 트라베세이루가 소개되며 신트라의 대표 과자로 자리 잡았습니다."
