          "history": "Restaurant Taverne is located in Hotel Interlaken; the hotel’s official history traces the property to a monastery inn mentioned in chronicles in 1323. It says that the then-owner, Louis Ross, renovated the house in 1491 and received official permission from the Bern authorities to operate an inn. The hotel says fragments of the original walls remain inside the Taverne restaurant, but it does not give a separate opening date for the restaurant."
