          "history": "Restaurant TaverneはHotel Interlaken内にあります。ホテルの公式沿革によると、この建物の前身は1323年の年代記に記された修道院の宿でした。同資料では、当時の所有者ルイ・ロスが1491年に建物を改修し、ベルン当局から宿の営業許可を得たとされています。Taverne店内には古い壁の一部が残ると説明されていますが、レストラン自体の開業年は示されていません。"
