          "history": "Restaurant Taverne은 Hotel Interlaken 안에 있으며, 호텔의 공식 역사 자료는 이 건물의 전신을 1323년 기록된 수도원 여관으로 설명합니다. 같은 자료에 따르면 당시 소유주 루이 로스는 1491년 건물을 개보수하고 베른 당국으로부터 여관 영업 허가를 받았습니다. 자료는 Taverne 식당 안에 옛 벽의 일부가 남아 있다고 하지만, 식당 자체의 별도 개업 연도는 밝히지 않습니다."
