          "history": "카페 임페리얼의 역사는 1914년 문을 연 호텔 임페리얼과 함께 시작됩니다. 그 전에 이 자리에는 U Černého orla(검은 독수리)라는 여관이 있었고, 콜라르조바 형제가 이를 매입해 철거한 뒤 새 호텔을 세웠습니다. 프라하 관광청은 건물의 아르데코풍 외관과 후기 아르누보 양식의 모자이크 장식을 소개합니다."
