          "history": "In 1516, the Republic of Venice compelled its Jewish residents to live in the Ghetto Nuovo in Cannaregio, an enclosed district bounded by canals whose gates were shut at night. As Jewish communities grew and diversified, the residential area expanded to the Ghetto Vecchio in 1541 and the Ghetto Nuovissimo in 1633. Napoleon’s removal of the gates in 1797 ended legal segregation."
