          "foodContext": "",
          "history": "1516년 베네치아 공화국은 유대인 주민들을 카나레조의 게토 누오보에 거주하도록 강제했으며, 운하와 출입문으로 둘러싸인 이 구역은 밤에는 폐쇄되었습니다. 유대인 공동체가 늘고 다양해지면서 1541년 게토 베키오, 1633년 게토 누오비시모로 거주 구역이 확대되었습니다. 나폴레옹이 1797년 게토의 문을 없애면서 법적 거주 분리가 끝났습니다."
