          "history": "The name ragù comes from the French *ragoût*, and Neapolitan ragù appears in written records from the 18th century. It is mentioned in Vincenzo Corrado’s 1773 cookbook and Ippolito Cavalcanti’s 1847 cookbook, but the earliest recorded versions were not made with tomatoes."
