          "ko": "비스테카 알라 피오렌티나는 토스카나식 T본 스테이크입니다. 1565년 산 로렌초 광장 잔치와 영어 “beef-steak” 외침에서 이름이 나왔다는 이야기는 작가의 설명을 전하는 전승이며, 확정된 기원으로 단정하지 않습니다.",
          "en": "Bistecca alla Fiorentina is a Tuscan-style T-bone steak. The story linking its name to a 1565 San Lorenzo Square feast and English cries of “beef-steak” is reported as an attributed tradition, not a proven origin.",
